 const checkBackend=useCallback(async()=>{setChecking(true);try{const r=await fetch('/api/status');const d=await r.json() as {ready?:boolean};setLive(d.ready===true);}catch{setLive(false);}finally{setChecking(false);}},[]);
 const generateOpening=useCallback(async(d:Draft)=>{const ac=new AbortController();controller.current=ac;const id=++runId.current;setBusy(true);setError('');try{const r=await fetch('/api/engine/opening',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(engineBody(d.scenario,d.profile,[],currentStore().sessions)),signal:ac.signal});if(!r.ok)throw new Error(await readError(r));const result=await r.json() as {reply:string;language:string};if(id!==runId.current)return;setMessages([{role:'assistant',content:result.reply}]);setReplyLanguage(result.language);playback.current?.setLanguage(result.language);playback.current?.beginTurn();playback.current?.enqueue(result.reply);}catch(e){if(!ac.signal.aborted)setError(e instanceof Error?e.message:'Could not generate an opening. Please retry.');}finally{if(id===runId.current)setBusy(false);}},[]);
 useEffect(()=>{if('speechSynthesis' in window&&'SpeechSynthesisUtterance' in window){playback.current=new SpeechPlayback(window.speechSynthesis,text=>new SpeechSynthesisUtterance(text),setSpeaking,message=>setNotice(message||'Spoken playback was interrupted. Replay the reply or use captions.'));}return()=>{playback.current?.stop();playback.current=null;};},[]);
