 useEffect(()=>{let active=true;let sequence=0;const restore=async()=>{const current=++sequence;await readyStore();if(!active||current!==sequence)return;if((drillActive.current||saveFailed.current||recorder.current?.state==='recording')&&!window.confirm('Some practice has not been finished or saved. Leave this screen anyway?')){if(lastURL.current)window.history.replaceState({},'',lastURL.current);return;}lastURL.current=window.location.href;cleanup();const route=parseRoute(window.location.href);await draftQueue.current;const state=currentStore();setError('');setNotice('');const preferences=settingValue<Profile>('clearroom.profile',defaultProfile);setProfile({...defaultProfile,...preferences});setView(route.view);if(route.view==='prepare'){const p=state.partners.find(p=>p.id===route.id);const s=p?partnerScenario(p):scenarios.find(s=>s.id===route.id);if(s){setScenario(s);setExperience(route.mode||'call');const lesson=lessons.find(l=>l.id===route.lessonId&&l.scenario===s.id);setSelectedLesson(lesson?.id);setProfile({...defaultProfile,...preferences,...(s.customPartner?{experience:'Some practice'}:{}),...(lesson?{difficulty:lesson.difficulty,goal:lesson.goal}:{})});}else{setView('home');setNotice('That partner is not saved on this browser.');}}else if(route.view==='create-partner'){setEditingPartner(state.partners.find(p=>p.id===route.id)||null);}else if(route.view==='practice'){const d=state.drafts.find(d=>d.id===route.id);if(!d){setView('home');setNotice('This draft is no longer available on this browser.');return;}draftRef.current=d;draftVersions.current.set(d.id,d.revision||0);closed.current=false;setScenario(d.scenario);setProfile(d.profile);setMessages(d.messages);setInput(d.input);setExperience(d.experience);setSeconds(d.seconds);setSelectedLesson(d.lessonId);setReplyLanguage(d.language);if(!d.messages.length)void generateOpening(d);}else if(route.view==='review'){const session=state.sessions.find(s=>s.id===route.id);if(session){setFeedback(session.feedback);setMessages(session.messages||[]);setReviewSaved(newReview.current!==session.id);const p=state.partners.find(p=>p.id===session.scenario);setScenario(p?partnerScenario(p):scenarios.find(s=>s.id===session.scenario)||{...scenarios[0],id:session.scenario,title:session.scenarioTitle||'Saved conversation',name:session.partnerName||'Partner'});}else{setView('progress');setNotice('This reflection is no longer saved.');}}window.scrollTo({top:0});};window.addEventListener('popstate',restore);window.addEventListener('clearroom:navigate',restore);void restore();void readyStore().then(checkBackend);return()=>{active=false;window.removeEventListener('popstate',restore);window.removeEventListener('clearroom:navigate',restore);cleanup();};},[cleanup,checkBackend,generateOpening]);
 useEffect(()=>{const frame=requestAnimationFrame(()=>{const title=main.current?.querySelector<HTMLElement>('h1');if(title){title.tabIndex=-1;title.focus({preventScroll:true});}});return()=>cancelAnimationFrame(frame);},[view]);
 useEffect(()=>{end.current?.scrollIntoView({behavior:'smooth',block:'nearest'});},[messages,busy]);
