 useEffect(()=>{if(view!=='practice')return;const timer=setInterval(()=>setSeconds(s=>s+1),1000);return()=>clearInterval(timer);},[view]);
 useEffect(()=>{if(view!=='practice'||!draftRef.current||closed.current)return;const copy={...draftRef.current,scenario,profile,messages,input,experience,language:replyLanguage,seconds:elapsed.current,date:new Date().toISOString()};saving.current=true;draftQueue.current=draftQueue.current.catch(()=>{}).then(async()=>{if(closed.current)return;copy.id=draftAliases.current.get(copy.id)||copy.id;try{const row=await saveItem('drafts',copy,draftVersions.current.get(copy.id)||copy.revision||0,copy.epoch||0);draftVersions.current.set(copy.id,row.revision);saveFailed.current=false;if(draftRef.current?.id===copy.id)draftRef.current={...copy,revision:row.revision};}catch(e){if(e instanceof StorageConflict){const fork={...copy,id:crypto.randomUUID()};const row=await saveItem('drafts',fork,0,fork.epoch||0);draftAliases.current.set(copy.id,row.id);draftVersions.current.set(row.id,row.revision);if(draftRef.current?.id===copy.id){draftRef.current={...fork,revision:row.revision};window.history.replaceState({},'',routeURL({view:'practice',id:row.id}));setNotice('Another tab changed this conversation. Your work was saved as a separate draft.');}}else if(e instanceof PracticeCleared){closed.current=true;moveRoute({view:'home'});}else{saveFailed.current=true;setNotice('Draft could not be saved. Keep this tab open or copy your words before leaving.');}}}).finally(()=>{saving.current=false;});},[view,messages,input,scenario,profile,experience,replyLanguage]);
 useEffect(()=>{const before=(e:BeforeUnloadEvent)=>{if(drillActive.current||(view==='practice'&&(busy||recording||saving.current||saveFailed.current||!!saved.error))){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',before);return()=>window.removeEventListener('beforeunload',before);},[view,busy,recording,saved.error]);
 function stopAudio(){playback.current?.stop();setSpeaking(false);}
 function toggleVoice(){setVoice(v=>!v);stopAudio();}
 function navigate(v:View){moveRoute({view:v});}
 function leavePractice(){navigate('home');}
 function prepare(s:Scenario,selectedExperience=experience){setSelectedLesson(undefined);setScenario(s);moveRoute({view:'prepare',id:s.id,mode:selectedExperience});}
 function openLesson(lesson:Lesson){setSelectedLesson(lesson.id);setProfile(p=>({...p,difficulty:lesson.difficulty,goal:lesson.goal}));setScenario(scenarios.find(s=>s.id===lesson.scenario)!);moveRoute({view:'prepare',id:lesson.scenario,mode:experience,lessonId:lesson.id});}
 function editPartner(p:CustomPartner|null){if(!p&&partners.length>=MAX_PARTNERS){setNotice('You have 12 partners. Edit or remove one before adding another.');return;}setEditingPartner(p);moveRoute({view:'create-partner',id:p?.id});}
 function startPartner(p:CustomPartner,selectedExperience:'chat'|'call'){setVoice(selectedExperience==='call');prepare(partnerScenario(p),selectedExperience);}
 async function savePartner(p:CustomPartner,selectedExperience?:'chat'|'call'){try{await saveItem('partners',p,p.revision||0);if(selectedExperience)startPartner(p,selectedExperience);else navigate('home');}catch(e){setNotice(e instanceof Error?e.message:'Could not save this partner.');}}
 async function deletePartner(id:string){const p=partners.find(p=>p.id===id);if(!p||!window.confirm(`Delete ${p.name}? Completed reflections remain in history.`))return;try{await removeItem('partners',id);setNotice(`${p.name} was removed.`);}catch{setNotice('Could not update browser storage.');}}
