 async function clearProgress(){if(!window.confirm('Clear all saved conversations, drafts, drills, and rewards? This also removes the past transcripts used by optional memory.'))return;try{closed.current=true;await draftQueue.current;await clearSavedPractice();setNotice('Practice history and drafts cleared across tabs.');}catch{setNotice('Could not clear browser storage.');}}
