 async function start(){if(!live){setError('AI is unavailable. Check the connection before starting a conversation.');return;}cleanup();const d:Draft={id:crypto.randomUUID(),date:new Date().toISOString(),scenario,profile,messages:[],input:'',experience,language:profile.language&&profile.language!=='auto'?profile.language:'en',seconds:0,epoch:Number(currentStore().settings.clearedAt||0),lessonId:selectedLesson};try{await saveItem('drafts',d,0);moveRoute({view:'practice',id:d.id});}catch{setError('Could not save a resumable draft. Enable browser storage and try again.');}}
 async function send(){const text=input.trim();if(!text||busy||recording)return;if(messages.filter(m=>m.role==='user').length>=12){setNotice('You’ve reached 12 turns. Get your feedback, then start a fresh attempt.');return;}stopAudio();setError('');setNotice('');const next:Message[]=[...messages,{role:'user',content:text}];setBusy(true);const id=++runId.current;const ac=new AbortController();controller.current=ac;
 try{const r=await fetch('/api/engine/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(engineBody(scenario,profile,next,history)),signal:ac.signal});if(!r.ok)throw new Error(await readError(r));if(!r.body)throw new Error('No reply received. Your message is ready to retry.');let language=replyLanguage;const reply=await readChatStream(r.body,code=>{language=code;});if(id!==runId.current)return;setMessages([...next,{role:'assistant',content:reply}]);setInput('');setReplyLanguage(language);playback.current?.setLanguage(language);playback.current?.beginTurn();playback.current?.enqueue(reply);
 }catch(e){if(!ac.signal.aborted&&id===runId.current){setError(e instanceof Error?e.message:'Could not connect. Your message is ready to retry.');stopAudio();}}finally{if(id===runId.current)setBusy(false);}}
 async function finish(){if(finishing.current||busy||recording||!messages.some(m=>m.role==='user'))return;finishing.current=true;stopAudio();setBusy(true);setError('');const id=++runId.current;const ac=new AbortController();controller.current=ac;try{const r=await fetch('/api/engine/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(engineBody(scenario,profile,messages,history)),signal:ac.signal});if(!r.ok)throw new Error(await readError(r));const f=await r.json() as Feedback;if(id!==runId.current)return;const entry:Session={lessonId:selectedLesson,id:draftRef.current?.id||crypto.randomUUID(),date:new Date().toISOString(),scenario:scenario.id,scenarioTitle:scenario.title,partnerName:scenario.name,turns:messages.filter(m=>m.role==='user').length,mode,feedback:f,messages,language:replyLanguage};closed.current=true;await draftQueue.current;entry.id=draftRef.current?.id||entry.id;const before=gameStats(currentStore().sessions,new Date(),dailyGoal,currentStore().drills);await saveItem('sessions',entry,undefined,draftRef.current?.epoch||0);if(draftRef.current)await removeItem('drafts',draftRef.current.id);const after=gameStats(currentStore().sessions,new Date(),dailyGoal,currentStore().drills);setReward({xp:after.xp-before.xp,badges:after.badges.filter(b=>b.earned&&!before.badges.find(old=>old.id===b.id)?.earned),levelUp:after.level>before.level});newReview.current=entry.id;moveRoute({view:'review',id:entry.id});}catch(e){closed.current=false;if(!ac.signal.aborted)setError(e instanceof Error?e.message:'Feedback is unavailable. Try again.');}finally{finishing.current=false;if(id===runId.current)setBusy(false);}}
 async function record(){if(recording){recorder.current?.stop();return;}if(!live){setNotice('AI voice transcription is currently unavailable.');return;}if(busy||acquiringMic.current)return;acquiringMic.current=true;stopAudio();setError('');const id=runId.current;try{const media=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});if(id!==runId.current){media.getTracks().forEach(t=>t.stop());return;}stream.current=media;const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(m=>MediaRecorder.isTypeSupported(m));const rec=new MediaRecorder(media,mime?{mimeType:mime}:{});recorder.current=rec;const chunks:BlobPart[]=[];recordingCancelled.current=false;rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};rec.onstop=async()=>{setRecording(false);if(recTimer.current)clearTimeout(recTimer.current);media.getTracks().forEach(t=>t.stop());if(recordingCancelled.current||id!==runId.current)return;setBusy(true);const ac=new AbortController();controller.current=ac;try{const blob=new Blob(chunks,{type:rec.mimeType});if(blob.size>4*1024*1024)throw new Error('That recording was too long. Try a shorter message.');const data=new FormData();data.append('file',blob,'voice');data.append('language',profile.language||'auto');const r=await fetch('/api/engine/transcribe',{method:'POST',body:data,signal:ac.signal});if(!r.ok)throw new Error(await readError(r));const d=await r.json() as {text?:string;language?:string};if(id===runId.current){setInput(d.text||'');if(d.language&&validLanguage(d.language)){setReplyLanguage(d.language);}setNotice(d.text?`Review your transcript (${d.language||'detected language'}), then send it.`:'No speech detected. Please try again.');}}catch(e){if(!ac.signal.aborted&&id===runId.current)setError(e instanceof Error?e.message:'Could not transcribe.');}finally{if(id===runId.current)setBusy(false);}};rec.start();setRecording(true);recTimer.current=setTimeout(()=>{if(rec.state==='recording')rec.stop();},45000);}catch{stream.current?.getTracks().forEach(t=>t.stop());stream.current=null;setRecording(false);setError('Microphone access was unavailable. Allow access in your browser, or type your response.');}finally{acquiringMic.current=false;}}
 async function adaptive(kind:DrillKind,options:GenerateOptions){const {signal,...requestOptions}=options;const r=await fetch('/api/engine/exercise',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...engineBody(scenario,profile,[],history),kind,...requestOptions,previous_feedback:history.find(h=>h.scenario===scenario.id)?.feedback.next_step?.slice(0,800)||''}),signal:AbortSignal.any([signal,AbortSignal.timeout(180000)])});if(!r.ok)throw new Error(await readError(r));return await r.json() as DrillSet;}
 const stats=gameStats(history,new Date(clock||0),dailyGoal,drillHistory);
